result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_curb65.py", "content": """"Tests for curb65: each criterion swept independently from a zero-point baseline."""

import pytest

from curb65 import curb65, InputRangeError

# Zero-point baseline patient: no confusion, normal labs/vitals, young adult.
BASE = dict(confusion=False, urea_mmol_l=4.0, rr=16, sbp=120, dbp=80, age=40)


def call(**overrides):
    kwargs = {**BASE, **overrides}
    return curb65(
        kwargs["confusion"],
        kwargs["urea_mmol_l"],
        kwargs["rr"],
        kwargs["sbp"],
        kwargs["dbp"],
        kwargs["age"],
    )


# --- Baseline ---------------------------------------------------------------

def test_baseline_is_zero_points_low():
    assert call() == (0, "low")


# --- Each criterion swept independently (one point at a time) ---------------

def test_confusion_alone():
    assert call(confusion=True) == (1, "low")


@pytest.mark.parametrize("urea", [7.5, 8.0, 10.0, 59.9])
def test_urea_above_threshold_alone(urea):
    assert call(urea_mmol_l=urea) == (1, "low")


@pytest.mark.parametrize("rr", [30, 31, 45, 80])
def test_rr_at_or_above_threshold_alone(rr):
    assert call(rr=rr) == (1, "low")


@pytest.mark.parametrize("sbp,dbp", [(89, 80), (90, 80), (120, 60), (150, 55)])
def test_low_blood_pressure_alone(sbp, dbp):
    assert call(sbp=sbp, dbp=dbp) == (1, "low")


@pytest.mark.parametrize("age", [65, 70, 100, 120])
def test_age_at_or_above_threshold_alone(age):
    assert call(age=age) == (1, "low")


# --- Pinned boundary cases ---------------------------------------------------

def test_urea_exactly_seven_gets_no_point():
    assert call(urea_mmol_l=7.0) == (0, "low")
    assert call(urea_mmol_l=7.000001) == (1, "low")  # just above flips it


def test_dbp_exactly_sixty_gets_a_point():
    assert call(dbp=60) == (1, "low")
    assert call(dbp=61) == (0, "low")  # just above removes it


# --- Bands --------------------------------------------------------------------

def test_two_points_intermediate():
    assert call(rr=32, age=70) == (2, "intermediate")


def test_three_points_high():
    assert call(confusion=True, rr=32, age=70) == (3, "high")


# --- Maximal 5-point patient --------------------------------------------------

def test_maximal_five_point_patient():
    score, band = curb65(
        confusion=True,
        urea_mmol_l=12.0,
        rr=34,
        sbp=85,
        dbp=50,
        age=78,
    )
    assert (score, band) == (5, "high")


# --- Guard rails --------------------------------------------------------------

@pytest.mark.parametrize(
    "field,value",
    [
        ("rr", 3), ("rr", 81),
        ("sbp", 39), ("sbp", 301),
        ("dbp", 19), ("dbp", 201),
        ("urea_mmol_l", 0.4), ("urea_mmol_l", 60.1),
        ("age", -1), ("age", 121),
    ],
)
def test_out_of_range_raises(field, value):
    with pytest.raises(InputRangeError):
        call(**{field: value})


def test_dbp_must_be_below_sbp():
    with pytest.raises(InputRangeError):
        call(sbp=100, dbp=100)
    with pytest.raises(InputRangeError):
        call(sbp=90, dbp=95)


def test_boundary_values_accepted():
    # Extreme-but-in-range values must not raise.
    assert call(rr=4, sbp=300, dbp=20, urea_mmol_l=0.5, age=0) == (
        2,
        "intermediate",
    )  # dbp<=60 and sbp<90 -> wait: sbp=300 not <90, dbp=20 <=60 -> 1 point... see below
